parameters.inputSchema:
{
  "type": "object",
  "required": [
    "aprobado",
    "motivo"
  ],
  "properties": {
    "aprobado": {
      "type": "boolean"
    },
    "motivo": {
      "type": "string"
    },
    "falla": {
      "type": "string",
      "enum": [
        "ninguna",
        "precio_inventado",
        "producto_equivocado",
        "dato_inventado",
        "no_contesta",
        "otra"
      ]
    },
    "queFalta": {
      "type": "string"
    },
    "mensajeCorregido": {
      "type": "string",
      "description": "el mensaje corregido, listo para enviar; vacio si el original estaba bien"
    },
    "queCorregi": {
      "type": "string",
      "description": "que le sacaste o cambiaste, en una linea"
    },
    "confianza": {
      "type": "number"
    }
  }
}
